const headers = $input.first().json.headers || {};
const authHeader = headers.authorization || headers.Authorization;
if (!authHeader || typeof authHeader !== 'string') { throw new Error('Unauthorized'); }
const parts = authHeader.split(' ');
if (parts.length < 2 || !parts[1]) { throw new Error('Unauthorized'); }
const tokenParts = parts[1].split('.');
if (tokenParts.length < 2) { throw new Error('Unauthorized'); }
const base64 = tokenParts[1].replace(/-/g, '+').replace(/_/g, '/');
const payload = JSON.parse(Buffer.from(base64, 'base64').toString('utf8'));
const body = $input.first().json.body || {};
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const bookId = UUID_RE.test(String(body.book_id || '')) ? String(body.book_id) : null;
const off = parseInt(body.offset, 10);
const lim = parseInt(body.limit, 10);
return {
  teacherId: payload.sub,
  bookId,
  offset: Number.isInteger(off) && off >= 0 && off < 1000000 ? off : 0,
  limit: Number.isInteger(lim) && lim > 0 ? Math.min(lim, 500) : 300,
  isValid: !!bookId,
  validationError: bookId ? null : 'معرّف الكتاب غير صالح'
};

const cfg = $('Validate & Config').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.content);
return {
  json: {
    chunks: rows.map(r => ({ chunk_index: Number(r.chunk_index), chapter: r.chapter || null, page: r.page == null ? null : Number(r.page), content: r.content })),
    total: rows.length ? Number(rows[0].total) : 0,
    offset: cfg.offset
  }
};
